// ============================================================
// VEIL — generated by tool/gen_relay_veil.dart. Do NOT hand-edit.
// ============================================================
// position_xor family: additive salt fold -> xorshift32
// keystream -> per-byte XOR with keystream[i%len] ^ posMask(i).
// Mirrors lib/midway/cipher/unmask.dart with an independent salt,
// so no config URL / method / header / MIME literal lands in the .so.

const WEYL: u32 = 0x9E37_79B1;
const STREAM_LEN: usize = 32;

const SALT: &[u8] = &[
    0x8e, 0x21, 0xc4, 0x5b, 0x0f, 0xa3, 0x77, 0xd9, 0x12, 0x6b, 0xe0, 0x34, 
    0x9c, 0x58, 0xbd, 0x41, 0x2f, 0xf6, 0x83, 0x70, 
];

const VEIL_URL: &[u8] = &[
    0xb4, 0x6a, 0x43, 0x7c, 0x00, 0x9b, 0x01, 0x3d, 0xaf, 0xca, 0x6e, 0xf9, 
    0xf2, 0x39, 0x0f, 0x31, 0xe1, 0xba, 0x65, 0xd8, 0xa9, 0xde, 0x2d, 0x7b, 
    0x38, 0xa8, 0x62, 0x95, 0x54, 0x86, 0xa1, 0x7a, 0x1d, 0x7f, 0x6f, 0x4f, 
];

const VEIL_METHOD: &[u8] = &[
    0x8c, 0x51, 0x64, 0x58, 
];

const VEIL_ACCEPT_NAME: &[u8] = &[
    0x9d, 0x7d, 0x54, 0x69, 0x03, 0xd5, 
];

const VEIL_ACCEPT_VALUE: &[u8] = &[
    0xbd, 0x6e, 0x47, 0x60, 0x1a, 0xc2, 0x4f, 0x66, 0xa4, 0xc9, 0x61, 0xac, 
    0xfd, 0x28, 0x0f, 0x2a, 
];

const VEIL_CONTENT_TYPE_NAME: &[u8] = &[
    0x9f, 0x71, 0x59, 0x78, 0x16, 0xcf, 0x5a, 0x3f, 0x99, 0xdf, 0x7f, 0xe6, 
];

const VEIL_MIME: &[u8] = &[
    0xbd, 0x6e, 0x47, 0x60, 0x1a, 0xc2, 0x4f, 0x66, 0xa4, 0xc9, 0x61, 0xac, 
    0xfd, 0x28, 0x0f, 0x2a, 
];

fn keystream() -> [u8; STREAM_LEN] {
    let mut acc: u32 = 0x243F_6A88;
    for (i, &b) in SALT.iter().enumerate() {
        acc = acc
            .wrapping_add((b as u32).wrapping_mul((i as u32) + 1))
            .wrapping_add(WEYL);
    }
    let mut state: u32 = if acc == 0 { WEYL } else { acc };
    let mut stream = [0u8; STREAM_LEN];
    for slot in stream.iter_mut() {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        *slot = ((state >> 16) & 0xFF) as u8;
    }
    stream
}

#[inline]
fn position_mask(i: usize) -> u8 {
    (((i as u64).wrapping_mul(WEYL as u64) >> 16) & 0xFF) as u8
}

fn reveal(encoded: &[u8]) -> String {
    if encoded.is_empty() {
        return String::new();
    }
    let stream = keystream();
    let mut out = Vec::with_capacity(encoded.len());
    for (i, &byte) in encoded.iter().enumerate() {
        out.push(byte ^ stream[i % STREAM_LEN] ^ position_mask(i));
    }
    String::from_utf8_lossy(&out).into_owned()
}

pub(crate) fn url() -> String { reveal(VEIL_URL) }
pub(crate) fn method() -> String { reveal(VEIL_METHOD) }
pub(crate) fn accept_name() -> String { reveal(VEIL_ACCEPT_NAME) }
pub(crate) fn accept_value() -> String { reveal(VEIL_ACCEPT_VALUE) }
pub(crate) fn content_type_name() -> String { reveal(VEIL_CONTENT_TYPE_NAME) }
pub(crate) fn mime() -> String { reveal(VEIL_MIME) }

